/**
 * Subset of the Tiled JSON map format (https://doc.mapeditor.org/en/stable/reference/json-map-format/)
 * that CatGen reads. Maps can be generated by tools/generate-world.ts or edited in Tiled.
 */
export interface TiledProperty {
  name: string;
  type: "string" | "int" | "float" | "bool" | "color" | "file" | "object" | "class";
  value: string | number | boolean;
}

export interface TiledObject {
  id: number;
  name: string;
  type: string;
  /** Tiled >= 1.9 uses `class` instead of `type`. */
  class?: string;
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: number;
  visible: boolean;
  point?: boolean;
  ellipse?: boolean;
  polygon?: { x: number; y: number }[];
  properties?: TiledProperty[];
}

export interface TiledTileLayer {
  type: "tilelayer";
  id: number;
  name: string;
  width: number;
  height: number;
  x: number;
  y: number;
  opacity: number;
  visible: boolean;
  data: number[];
}

export interface TiledObjectLayer {
  type: "objectgroup";
  id: number;
  name: string;
  x: number;
  y: number;
  opacity: number;
  visible: boolean;
  draworder: "topdown" | "index";
  objects: TiledObject[];
}

export type TiledLayer = TiledTileLayer | TiledObjectLayer;

export interface TiledMap {
  type: "map";
  version: string;
  tiledversion: string;
  orientation: "orthogonal";
  renderorder: "right-down";
  width: number;
  height: number;
  tilewidth: number;
  tileheight: number;
  infinite: false;
  nextlayerid: number;
  nextobjectid: number;
  layers: TiledLayer[];
  tilesets: {
    firstgid: number;
    name: string;
    tilewidth: number;
    tileheight: number;
    tilecount: number;
    columns: number;
    image: string;
    imagewidth: number;
    imageheight: number;
    margin: number;
    spacing: number;
  }[];
  properties?: TiledProperty[];
}

export function prop<T extends string | number | boolean>(obj: { properties?: TiledProperty[] }, name: string, fallback: T): T {
  const p = obj.properties?.find((x) => x.name === name);
  return (p ? p.value : fallback) as T;
}

export function objectType(o: TiledObject): string {
  return o.type || o.class || "";
}
